from __future__ import annotations

import stat
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

HOOK_MARKER = "# managed-by: aimes"
CONFIRM_WORD = "HOOK"

PRE_COMMIT_TEMPLATE = """#!/bin/sh
{marker}
# AIMES governance pre-commit gate. Generated by `aimes hook install --type pre-commit`.
# It only runs read-only AIMES checks; remove the file (or unset core.hooksPath) to disable.
if [ -f .aimes/config.yaml ]; then
    if command -v aimes >/dev/null 2>&1; then
        aimes validate --root . || {{ echo "AIMES validate failed"; exit 1; }}
    elif command -v python >/dev/null 2>&1 && python -c "import aimes_cli" 2>/dev/null; then
        python -m aimes_cli.cli validate --root . || {{ echo "AIMES validate failed"; exit 1; }}
    else
        echo "AIMES CLI not found; install it or remove this hook to keep commits unblocked." >&2
        exit 1
    fi
fi
exit 0
"""


def _generated(text: str) -> bool:
    return HOOK_MARKER in text


def hook_path(root: Path, hook_type: str) -> Path:
    return root / "hooks" / hook_type


def plan_hook_install(root: Path, hook_type: str = "pre-commit") -> dict[str, Any]:
    if hook_type != "pre-commit":
        raise ValueError(f"Unsupported hook type: {hook_type}")
    target = hook_path(root, hook_type)
    content = PRE_COMMIT_TEMPLATE.format(marker=HOOK_MARKER)
    actions: list[dict[str, str]] = []
    findings: list[dict[str, str]] = []
    if target.exists():
        existing = target.read_text(encoding="utf-8", errors="replace")
        if existing == content:
            actions.append({"path": str(target), "action": "unchanged"})
        elif _generated(existing):
            actions.append({"path": str(target), "action": "update-managed"})
        else:
            actions.append({"path": str(target), "action": "preserved-user-hook"})
            actions.append({"path": str(root / ".aimes/proposed/hooks" / hook_type), "action": "write-proposal"})
            findings.append({"level": "WARNING", "code": "HOOK_USER_OWNED",
                             "message": f"{target} is not AIMES-managed; it will be preserved and the generated version staged as a proposal."})
    else:
        actions.append({"path": str(target), "action": "create"})
    if not (root / ".git").exists():
        findings.append({"level": "WARNING", "code": "GIT_DIR_NOT_FOUND",
                         "message": "No .git directory at the project root; the hook file can still be created but Git will not execute it until core.hooksPath is configured."})
    git_hooks_active = (root / ".git/hooks" / hook_type).exists() if (root / ".git").is_dir() else False
    return {
        "hook_type": hook_type,
        "target": str(target),
        "content_preview": content,
        "actions": actions,
        "findings": findings,
        "git_hooks_active": git_hooks_active,
        "activation_hint": f"Preview only. To write the file rerun with --apply --confirm {CONFIRM_WORD}; Git executes it when `git config core.hooksPath hooks` is set.",
    }


def apply_hook_install(root: Path, hook_type: str = "pre-commit", confirm: str | None = None) -> dict[str, Any]:
    plan = plan_hook_install(root, hook_type)
    if not confirm or confirm.strip().upper() != CONFIRM_WORD:
        raise ValueError(f"Applying hooks requires --confirm {CONFIRM_WORD}; files were not modified.")
    target = Path(plan["target"])
    content = plan["content_preview"]
    written: list[dict[str, str]] = []
    actions = {item["action"] for item in plan["actions"]}
    if "create" in actions or "update-managed" in actions:
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8", newline="\n")
        try:
            target.chmod(target.stat().st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
        except OSError:
            pass
        written.append({"path": str(target), "action": "write"})
    if "write-proposal" in actions:
        proposal = root / ".aimes/proposed/hooks" / hook_type
        proposal.parent.mkdir(parents=True, exist_ok=True)
        proposal.write_text(content, encoding="utf-8", newline="\n")
        written.append({"path": str(proposal), "action": "write-proposal"})
    plan.update({
        "ok": True,
        "dry_run": False,
        "applied_at": datetime.now(timezone.utc).replace(microsecond=0).isoformat(),
        "written": written,
    })
    return plan
